+                    // Skipper moved
+                    assert newDocUpto % BLOCK_SIZE == 0 : "got " + newDocUpto;
+                    docUpto = newDocUpto;
+
+                    // Force to read next block
+                    docBufferUpto = BLOCK_SIZE;
+                    accum = skipper.getDoc();
