+        int numArcs;
+        Arc<T>[] arcs;
+        // TODO: instead of recording isFinal/output on the
+        // node, maybe we should use -1 arc to mean "end" (like
+        // we do when reading the FST). Would simplify much
+        // code here...
+        T output;
+        boolean isFinal;
+        long inputCount;
+
+        /** This node's depth, starting from the automaton root. */
+        final int depth;
+
+        /**
