+        for (int version = PackedInts.VERSION_START; version <= PackedInts.VERSION_CURRENT; version++) {
+            for (PackedInts.Format format : PackedInts.Format.values()) {
+                for (int bpv = 1; bpv <= 32; ++bpv) {
+                    if (format.isSupported(bpv) == false) {
