+                // First bit must be set.
+                assert isBitSet(0, arc, in);
+                // Last bit must be set.
+                assert isBitSet(arc.numArcs() - 1, arc, in);
+                // No bit set after the last arc.
+                assert nextBitSet(arc.numArcs() - 1, arc, in) == -1;
+                return true;
+            }
+        }
+    }
